import fs from 'node:fs';
const file='docs/research/venue-candidates-20261107.json',r=JSON.parse(fs.readFileSync(file,'utf8'));
const names={'hoi-an-anantara':'Anantara','da-lat-dalat-palace':'Dalat Palace','nha-trang-havana':'Havana','buon-ma-thuot-dakruco':'Dakruco','cao-bang-muong-thanh':'Mường Thanh','ha-long-wyndham-legend':'Wyndham Legend','phong-nha-farmstay':'Phong Nha Farmstay','ha-giang-hmong-village':'Hmong Village','ta-xua-thac-may':'Thác Mây','phu-yen-stelia':'Stelia','quy-nhon-avani':'Avani','sa-pa-viettrekking':'Viettrekking','nha-trang-nem-dang-van-quyen':'Đặng Văn Quyên','phu-quoc-kien-xay':'Kiến Xây','phong-nha-pub-cold-beer':'Pub with cold beer'};
for(const [key,q] of Object.entries(names)){const v=r['venue-'+key];if(v.shortHits)continue;const d=JSON.parse(fs.readFileSync('backend/src/main/resources/catalog/'+v.dest+'.json','utf8'));const center=d.reference??d.center??d;console.log(v.id,'center',JSON.stringify(center).slice(0,150));const params=new URLSearchParams({q,countrycodes:'vn',format:'jsonv2',limit:'6'});try{const res=await fetch('https://nominatim.openstreetmap.org/search?'+params,{headers:{'User-Agent':'WanderCatalog/0.1 (contact: binkuteqn289@gmail.com)'},signal:AbortSignal.timeout(20000)});if(!res.ok)throw Error('HTTP '+res.status);v.shortHits=await res.json();console.log(v.id,JSON.stringify(v.shortHits.map(h=>({lat:h.lat,lon:h.lon,type:h.type,name:h.display_name,id:h.osm_id}))));}catch(e){console.log(e.message);}fs.writeFileSync(file,JSON.stringify(r,null,2)+'\n');await new Promise(r=>setTimeout(r,1300));}
